void swe_observation_b(int n, int m, int step, int stride, const int indices[m
        ], const double observations[], double sigma, const double state[3*n],
        double stateb[3*n], double *cost, double *costb) {
    int p;
    int cycle = (step+1)/stride - 1;
    double residual;
    double residualb;
    for (p = m-1; p > -1; --p) {
        residual = (state[indices[p]]-observations[cycle*m+p])/sigma;
        residualb = 2*residual*0.5*(*costb);
        stateb[indices[p]] = stateb[indices[p]] + residualb/sigma;
    }
}

/* Keep the residual calculation in a routine: it is replayed locally by AD. 
*/
void swe_observation_nodiff(int n, int m, int step, int stride, const int 
        indices[m], const double observations[], double sigma, const double 
        state[3*n], double *cost) {
    int p;
    int cycle = (step+1)/stride - 1;
    double residual;
    for (p = 0; p < m; ++p) {
        residual = (state[indices[p]]-observations[cycle*m+p])/sigma;
        *cost += 0.5*residual*residual;
    }
}

